type Infer<T> = T extends { a: infer U; b: infer U } ? U : "miss";
declare const value: Infer<{ a: string; b: number }>;
export const result = value;
export const check: string | number = result;

type Infer<T> = T extends { a: (x: infer U) => void; b: (x: infer U) => void } ? U : "miss";
declare const value: Infer<{ a: (x: string) => void; b: (x: number) => void }>;
export const result = value;
export const check: never = result;

type Infer<T> = T extends { a: (x: infer U) => void; b: (x: infer U) => void } ? U : "miss";
declare const value: Infer<{ a: (x: "a" | "b") => void; b: (x: "b" | "c") => void }>;
export const result = value;
export const check: "b" = result;

type Infer<T> = T extends { a: (x: infer U) => void; b: (x: infer U) => void } ? U : "miss";
declare const value: Infer<{ a: (x: { a: string }) => void; b: (x: { b: number }) => void }>;
export const result = value;
export const check: { a: string; b: number } = result;

type Infer<T> = T extends { a: (x: infer U) => void; b: (x: infer U) => void } ? U : "miss";
declare const value: Infer<{ a: (x: string) => void; b: (x: number) => void }>;
export const result = value;
export const rejected: typeof result = "wrong";

type Infer<T> = T extends (x: infer U) => infer U ? U : "miss";
declare const value: Infer<(x: string) => "ok">;
export const result = value;
export const check: "ok" = result;

type Infer<T> = T extends (x: infer U) => infer U ? U : "miss";
declare const value: Infer<(x: "narrow") => string>;
export const result = value;
export const check: "miss" = result;

type Infer<T> = T extends (f: (x: infer U) => void) => void ? U : "miss";
declare const value: Infer<(f: (x: "ok") => void) => void>;
export const result = value;
export const check: "ok" = result;

type Infer<T> = T extends (x: infer U) => void ? U : "miss";
declare const value: Infer<() => void>;
export const result = value;

type Infer<T> = T extends (x: infer U) => void ? U : "miss";
declare const value: Infer<() => void>;
export const result = value;
export const check: "miss" = result;

type Infer<T> = T extends (x?: infer U) => void ? U : "miss";
declare const value: Infer<() => void>;
export const result = value;

type Infer<T> = T extends (x: infer U extends string) => void ? U : "miss";
declare const value: Infer<() => void>;
export const result = value;
export const check: string = result;

type Infer<T> = T extends (...args: any[]) => infer U ? U : "miss";
declare const value: Infer<(x: number) => "ok">;
export const result = value;
export const check: "ok" = result;

type Infer<T> = T extends (x: infer U) => void ? U : "miss";
declare const value: Infer<{ (x: "first"): void; (x: "last"): void }>;
export const result = value;
export const check: "last" = result;

type Infer<T> = T extends readonly (infer U)[] ? U : "miss";
declare const value: Infer<readonly string[]>;
export const result = value;
export const check: string = result;

type Infer<T> = T extends [infer H, ...infer R] ? [H, R] : "miss";
declare const value: Infer<[string, number, boolean]>;
export const result = value;
export const check: [string, [number, boolean]] = result;

type Infer<T> = T extends [...infer R, infer L] ? [R, L] : "miss";
declare const value: Infer<[string, number, boolean]>;
export const result = value;
export const check: [[string, number], boolean] = result;

type Infer<T> = T extends [(infer H)?, ...infer R] ? [H, R] : "miss";
declare const value: Infer<[]>;
export const result = value;

type Infer<T> = T extends string ? 1 : 2;
declare const value: Infer<any>;
export const result = value;
export const check: 1 | 2 = result;

type Infer<T> = T extends string ? 1 : 2;
declare const value: Infer<never>;
export const result = value;
export const check: never = result;

type Infer<T> = [T] extends [string] ? 1 : 2;
declare const value: Infer<string | number>;
export const result = value;
export const check: 2 = result;

type Infer<T> = T extends { a: infer U extends string; b: infer U extends string } ? U : "miss";
declare const value: Infer<{ a: "a"; b: "b" }>;
export const result = value;
export const check: "a" | "b" = result;

import type { Infer } from "./types";
declare const value: Infer<{ a: (x: string) => void; b: (x: number) => void }>;
export const result = value;
export const check: never = result;

type Callback<X> = (value: X) => void;
type Infer<T> = T extends { a: Callback<infer U>; b: Callback<infer U> } ? U : "miss";
declare const value: Infer<{ a: Callback<string>; b: Callback<number> }>;
export const result = value;
export const check: never = result;

declarations.main.d.ts:
export declare const result: {
    a: string;
} & {
    b: number;
};
export declare const check: {
    a: string;
    b: number;
};

declarations.types.d.ts:
export type Infer<T> = T extends {
    a: (x: infer U) => void;
    b: (x: infer U) => void;
} ? U : "miss";
